    7.1.0

     Параметр offset теперь поддерживает отрицательные значения.

  &reftitle.examples;

   Пример использования grapheme_strpos


<?php

// Символ | Название | Кодовая точка | Форма нормализации

// å: 'LATIN SMALL LETTER A WITH RING ABOVE', U+00E5, NFD
$char_a_ring_nfd = "a\xCC\x8A";

// ö: 'LATIN SMALL LETTER O WITH DIAERESIS', U+00F6, NFD
$char_o_diaeresis_nfd = "o\xCC\x88";

print grapheme_strpos(
    $char_a_ring_nfd . $char_a_ring_nfd . $char_o_diaeresis_nfd,
    $char_o_diaeresis_nfd
);



  &example.outputs;


2



   Пример различения селекторов вариантов ключом локали ks-identic

    По умолчанию селекторы вариантов Unicode (U+FE0E — текстовый, U+FE0F — эмодзи)
    при сравнении игнорируются. Ключ расширения локали ks-identic
    включает сопоставление на идентичном уровне, при котором селекторы считаются разными символами.



     Параметр locale доступен начиная с PHP 8.5.0.




<?php

$textStyle ="\u{263A}\u{FE0E}"; // U+263A + U+FE0E (селектор текстового представления)
$emojiStyle = "\u{263A}\u{FE0F}"; // U+263A + U+FE0F (селектор представления эмодзи)

// Локаль по умолчанию: селекторы вариантов игнорируются, поэтому подстрока найдена в позиции 0.
var_dump(grapheme_strpos($textStyle, $emojiStyle));

// С ключом ks-identic селекторы вариантов значимы, поэтому совпадение не найдено.
var_dump(grapheme_strpos($textStyle, $emojiStyle, 0, 'en_US-u-ks-identic'));


   &example.outputs;


